/* Scenario-local evaluation suites and reusable case library. All records are local Mock state. */
const evAssetState={suiteSearch:'',caseSearch:'',caseTag:'',caseStatus:'active',picker:null,import:null};
let evSuiteEditor=null;
function evAssetButton(label,code,cls='ont-link'){const classes={'ev-link':'ont-link','ev-primary':'ont-button strong','ev-secondary':'ont-button'};return `<button type="button" class="${classes[cls]||cls}" onclick="${code}">${esc(label)}</button>`;}
function evAssetText(value){return `<span class="ev-cell-text ev-ellipsis" title="${esc(value||'')}">${esc(value||'—')}</span>`;}
function evAssetEmpty(title,description,actions=''){return `<div class="ont-empty"><p>${esc(title)}</p><small>${esc(description)}</small>${actions?`<div class="ev-actions">${actions}</div>`:''}</div>`;}
function evVisibleSuites(){const d=evData(),ids=new Set(evFilteredTasks().map(t=>t.id)),filtered=!!(evState.agentIds?.length||evState.objectIds?.length);return d.suites.filter(s=>evFilterMatch('suite','agent',s.agentId)&&(!filtered||s.taskIds.some(id=>ids.has(id)))&&(!evAssetState.suiteSearch||[s.id,s.name,s.target].join(' ').toLowerCase().includes(evAssetState.suiteSearch.toLowerCase())));}
function evSuitesView(){const suites=evVisibleSuites(),cases=suites.flatMap(evSuiteCases),tasks=suites.flatMap(evSuiteCoveredTasks);return `<div id="ev-suite-results">${evDashboardBar('suite-list',evDashboardSuiteMetrics(suites,cases,tasks))}${evSuiteTable(suites)}</div>`;}
function evSuiteTable(rows,contentOnly=false){const d=evData(),headers=['编号','名称',evFilterHeader('所属 Agent','suite','agent',evAgents()),'测试目标','版本','评测用例数','覆盖业务任务数','操作'],items=rows.map(s=>`<tr><td><span class="ont-id">${esc(s.id)}</span></td><td><button type="button" class="ont-link" onclick="evOpenSuite('${s.id}')">${esc(s.name)}</button></td><td>${esc(evAgentName(s.agentId))}</td><td>${evAssetText(s.target)}</td><td>${evVersionBadge(s)}</td><td>${s.caseIds.filter(id=>d.cases.some(c=>c.id===id&&!c.archived)).length}</td><td>${evSuiteCoveredTasks(s).length}</td><td><div class="ev-actions">${evAssetButton('查看',`evOpenSuite('${s.id}')`)}${evMore([{label:'编辑',code:`evEditSuite('${s.id}')`},{label:'发布',code:`evPublishResource('suite','${s.id}')`},{label:'删除',code:`evDeleteSuite('${s.id}')`,danger:true}])}</div></td></tr>`),empty=evAssetEmpty(d.suites.length?'暂无匹配的评测集':'暂无评测集',d.suites.length?'调整搜索或资源筛选后重试。':'点击新建，选择业务任务并设置测试目标。'),toolbar=`<label class="ont-search"><input aria-label="搜索评测集" placeholder="搜索编号、名称或测试目标" value="${esc(evAssetState.suiteSearch)}" oninput="evAssetState.suiteSearch=this.value;evAssetRefresh('suite')"><svg viewBox="0 0 18 18"><circle cx="7" cy="7" r="5"/><path d="m11 11 4 4"/></svg></label><div class="ont-head-actions"><button type="button" class="ont-button" onclick="evTab('评测用例库')">评测用例库</button>${evCreateMenu('suite')}</div>`;return contentOnly?evTableContent(headers,items,empty):evTable(headers,items,empty,toolbar);}
function evAssetRefresh(kind){if(kind==='suite'||kind==='case')evRefreshList(kind);else if(kind==='picker')evRefreshCasePicker();}
function evSuiteTasks(agentId){const d=evData();if(!agentId||!evAgents().some(a=>a.id===agentId))return [];return d.tasks.filter(t=>t.agentId===agentId);}
function evBuildSuiteDraft(fields={}){const d=evData(),allowed=new Set(evAgents().map(a=>a.id)),explicit=Array.isArray(fields.taskIds)?fields.taskIds:null,owners=explicit?[...new Set(explicit.map(id=>d.tasks.find(t=>t.id===id)?.agentId).filter(id=>allowed.has(id)))]:[],agentId=allowed.has(fields.agentId)?fields.agentId:!fields.agentId&&owners.length===1?owners[0]:'',tasks=evSuiteTasks(agentId),valid=new Set(tasks.map(t=>t.id)),target=fields.target||fields['测试目标']||fields.request||'验证业务任务的输出完整性、规则遵循与异常处理能力。';return {name:fields.name||fields['评测集名称']||`${studioSceneData[d.scene].name}场景业务验收`,target:target+(fields.instructions?'\n补充要求：'+fields.instructions:''),agentId,taskIds:explicit?[...new Set(explicit.filter(id=>valid.has(id)))]:tasks.slice(0,2).map(t=>t.id)};}
function evSuiteTaskOptions(agentId,selected=[]){
  const tasks=evSuiteTasks(agentId);
  if(!agentId||!tasks.length)return `<div class="ev-multiselect"><button type="button" class="ev-multiselect-trigger" aria-label="选择业务任务" disabled><span>${agentId?'该 Agent 暂无业务任务':'请先选择 Agent'}</span>${evDropdownArrow()}</button></div>`;
  return evMultiSelect({name:'taskIds',label:'选择业务任务',searchable:true,searchPlaceholder:'搜索业务任务名称或编号',options:tasks.map(t=>({id:t.id,name:t.name,description:t.version})),selected:selected.filter(id=>tasks.some(t=>t.id===id)),onchange:'evSuitePickTask(this.value,this.checked)'});
}

function evSuitePickTask(id,checked){const e=evSuiteEditor;if(!e||e.scene!==studio.scene||!evSuiteTasks(e.agentId).some(t=>t.id===id))return;e.taskIds=checked?[...new Set([...e.taskIds,id])]:e.taskIds.filter(x=>x!==id);}
function evSuiteAgentChange(selectOrString){const e=evSuiteEditor;if(!e||e.scene!==studio.scene)return;const value=typeof selectOrString==='string'?selectOrString:selectOrString?.value||'',agentId=evAgents().some(a=>a.id===value)?value:'';const control=typeof selectOrString==='string'?document.getElementById('ev-suite-agent'):selectOrString;if(control)control.value=agentId;if(e.agentId===agentId)return;e.agentId=agentId;e.taskIds=[];const options=document.getElementById('ev-suite-task-options'),save=document.getElementById('ev-suite-save');if(options)options.innerHTML=evSuiteTaskOptions(agentId);if(save)save.disabled=!evSuiteTasks(agentId).length;const publish=document.getElementById('ev-suite-publish');if(publish)publish.disabled=!evSuiteTasks(agentId).length;}
function evEditSuite(id='',draft=null){const d=evData(),suite=d.suites.find(s=>s.id===id);if(id&&!suite){toast('评测集已不存在或不属于当前场景');return;}const s=suite||draft||{},agents=evAgents(),agentId=agents.some(a=>a.id===s.agentId)?s.agentId:'',tasks=evSuiteTasks(agentId),taskIds=(s.taskIds||[]).filter(id=>tasks.some(t=>t.id===id)),copilot=!id&&draft&&draft===evState.copilot?.draft&&evState.copilot.kind==='suite';evSuiteEditor={scene:d.scene,id,agentId,taskIds:[...taskIds]};const body=`<input type="hidden" name="scene" value="${d.scene}"><input type="hidden" name="copilot" value="${copilot?'true':'false'}"><section class="ont-form-section"><h3>基本信息</h3><div class="ont-grid">${evField('所属 Agent',`<select id="ev-suite-agent" name="agentId" aria-label="评测集所属 Agent" required onchange="evSuiteAgentChange(this)"><option value="">请选择 Agent</option>${agents.map(a=>`<option value="${a.id}" ${a.id===agentId?'selected':''}>${esc(a.name)}${a.scope==='application'?' · 所属应用':''}</option>`).join('')}</select>`)}${evField('评测集名称',`<input name="name" aria-label="评测集名称" maxlength="100" required value="${esc(s.name||'')}" placeholder="请输入评测集名称">`)}<div class="ont-wide">${evField('测试目标',`<textarea name="target" aria-label="测试目标" maxlength="3000" required placeholder="描述需要验证的业务能力和结果">${esc(s.target||'')}</textarea>`)}</div></div></section><section class="ont-form-section"><div class="ont-section-title"><h3>业务任务 <i class="ont-required">*</i></h3><small>可多选，仅显示所选 Agent 的任务</small></div><div id="ev-suite-task-options" class="ev-suite-task-select">${evSuiteTaskOptions(agentId,taskIds)}</div></section>`;evModal(suite?'编辑评测集':draft?'确认 Copilot 评测集草案':'新建评测集',body,`<button type="submit" id="ev-suite-save" value="save" class="ont-button" ${tasks.length?'':'disabled'}>保存</button><button type="submit" id="ev-suite-publish" value="publish" class="ont-button strong" ${tasks.length?'':'disabled'}>发布</button>`,`evSaveSuite(this,'${id}',event.submitter?.value==='publish')`,suite?evVersionSwitcher('suite',suite,'current','edit'):'');}
function evSaveSuite(form,id='',publish=false){const d=evData(),f=new FormData(form);if((f.get('scene')&&f.get('scene')!==d.scene)||(id&&!d.suites.some(s=>s.id===id))){toast('当前场景已变更，请重新打开评测集');return false;}const agentId=String(f.get('agentId')||''),taskIds=[...new Set(f.getAll('taskIds'))],name=String(f.get('name')||'').trim(),target=String(f.get('target')||'').trim();if(!evAgents().some(a=>a.id===agentId)){toast('请先选择当前场景或所属应用的一个 Agent');return false;}if(!name||!target||!taskIds.length){toast('请填写名称、测试目标，并选择至少一个业务任务');return false;}const allowed=new Set(evSuiteTasks(agentId).map(t=>t.id));if(taskIds.some(id=>!allowed.has(id))){toast('所选业务任务必须全部属于当前选择的 Agent，请重新选择');return false;}const prior=d.suites.find(s=>s.id===id);let saved=prior;if(prior){if(!prior.createdAt)prior.createdAt=new Date().toISOString();evVersionPrepare(prior);Object.assign(prior,{name,target,agentId,taskIds});}else {const item={id:evId('suite'),name,target,agentId,taskIds,caseIds:[],createdAt:new Date().toISOString()};d.suites.unshift(item);evState.suiteId=item.id;evState.suiteTab='评测用例';saved=item;}saved.taskSnapshots=evVersionClone(d.tasks.filter(t=>taskIds.includes(t.id)));saved.caseBindings=Object.fromEntries((saved.caseIds||[]).map(id=>[id,evCaseBindings(saved,id)]));evVersionSave(saved);if(publish)evVersionPublish(saved);if(!prior&&f.get('copilot')==='true'&&typeof evCopilotSaved==='function')evCopilotSaved('suite',saved);evSuiteEditor=null;evCloseModal();evState.tab='评测集';evRender();toast(publish?'评测集已发布 '+saved.version:prior?'评测集已保存，发布后生成版本':'评测集已保存，可以添加评测用例后发布');return true;}
function evOpenSuite(id,tab='评测用例'){if(!evData().suites.some(s=>s.id===id))return false;evVersionSetSelection('suite',id);evState.suiteId=id;evState.suiteTab=['评测用例','评测集配置'].includes(tab)?tab:'评测用例';evState.tab='评测集';evRender();return true;}
function evSuiteBack(){evState.suiteId=null;evState.suiteTab='评测用例';evState.tab='评测集';evRender();}
function evSuiteSelectTab(tab){if(!evState.suiteId||!['评测用例','评测集配置'].includes(tab))return;evState.suiteTab=tab;evRender();}
function evDeleteSuite(id){const s=evData().suites.find(s=>s.id===id);if(!s)return;evModal('删除评测集',`<p>确定删除「${esc(s.name)}」？</p><p class="muted">评测用例库中的原始用例将保留。</p>`,`<button type="button" class="ont-button danger" onclick="evConfirmDeleteSuite('${id}','${studio.scene}')">删除评测集</button>`);}
function evConfirmDeleteSuite(id,scene=studio.scene){const d=evData();if(scene!==d.scene){toast('当前场景已变更，请重新操作');return false;}d.suites=d.suites.filter(s=>s.id!==id);if(evState.suiteId===id)evState.suiteId=null;evCloseModal();evRender();toast('评测集已删除');}
function evSuiteCases(s){const d=evData();return s.caseIds.map(id=>d.cases.find(c=>c.id===id&&!c.archived)).filter(Boolean);}
function evSuiteLinkedTasks(s){const d=evData();return s.taskIds.map(id=>(s.taskSnapshots||[]).find(t=>t.id===id)||d.tasks.find(t=>t.id===id)).filter(Boolean);}
function evSuiteDashboardData(s){return {scope:'suite:'+s.id,cases:evSuiteCases(s),tasks:evSuiteLinkedTasks(s)};}
function evSuiteDetailActions(s){if(evVersionSelection('suite',s.id)!=='current')return evAssetButton('返回当前版本',`evVersionSelect('suite','${s.id}','current','${evVersionContext('suite',s.id)}')`,'ont-button');return evAssetButton('编辑',`evEditSuite('${s.id}')`,'ont-button')+evAssetButton('发布',`evPublishResource('suite','${s.id}')`,'ont-button strong');}
function evSuiteDetailTabs(s){const tabs=[['评测用例',evSuiteCases(s).length],['评测集配置',null]];return `<nav class="ont-tabs ev-detail-tabs" aria-label="评测集详情页签">${tabs.map(([name,count])=>`<button type="button" class="${name===evState.suiteTab?'active':''}" onclick="evSuiteSelectTab('${name}')">${name}${count===null?'':`<span class="ont-count">${count}</span>`}</button>`).join('')}</nav>`;}
function evSuiteView(s){
 const {scope,cases,tasks}=evSuiteDashboardData(s),readonly=evVersionSelection('suite',s.id)!=='current';
 if(evState.suiteTab!=='评测集配置')return evDashboardBar(scope,evSuiteCoverageMetrics(s))+evTable(['编号','名称','输入','预期结果','业务任务','评估维度','标签','版本','状态','操作'],cases.map(c=>evCaseRow(c,s.id,readonly,s)),evAssetEmpty('暂无评测用例','添加用例并关联业务任务及评估维度，形成覆盖。'),readonly?'':`<span></span><div class="ont-head-actions">${evSuiteAddMenu(s.id)}</div>`);
 return `<section class="ont-overview ev-suite-overview"><div class="ont-section-title"><h3>基本信息</h3></div><dl class="ont-mapping ev-detail-mapping"><div><dt>编号</dt><dd><span class="ont-id">${esc(s.id)}</span></dd></div><div><dt>名称</dt><dd>${esc(s.name)}</dd></div><div><dt>所属 Agent</dt><dd>${esc(evAgentName(s.agentId))}</dd></div><div><dt>版本 / 发布状态</dt><dd>${evVersionBadge(s)}</dd></div><div class="ont-wide"><dt>测试目标</dt><dd class="ev-preserve-text">${esc(s.target)}</dd></div></dl></section><section class="ont-overview"><div class="ont-section-title"><h3>相关业务任务</h3><span class="muted">覆盖分母以这些任务及其评估维度为准</span></div>${evTable(['编号','名称','所属 Agent','版本','评估维度','操作'],evTaskRows(tasks,true),evAssetEmpty('暂无业务任务','编辑评测集，选择所属 Agent 的业务任务。'))}</section>`;
}

function evSuiteAddMenu(id){return `<details class="ev-add-menu"><summary class="ont-button strong">＋ 添加评测用例 ${evDropdownArrow()}</summary><div class="wi-card-menu" role="menu">${evAssetButton('从用例库选择',`evOpenCasePicker('${id}')`)}${evAssetButton('手动录入',`evEditCase('','${id}')`)}${evAssetButton('Copilot 生成',`evCopilot('case',{suiteId:'${id}'})`)}${evAssetButton('上传导入',`evImportCases('${id}')`)}</div></details>`;}
function evCaseTags(c){return c.tags.length?c.tags.map(t=>`<span class="ont-badge">${esc(t)}</span>`).join(' '):'<span class="muted">—</span>';}
function evVisibleCases(){const d=evData(),q=evAssetState.caseSearch.toLowerCase();return d.cases.filter(c=>!c.archived&&evFilterMatch('case','tags',c.tags)&&evFilterMatch('case','enabled',c.enabled?'enabled':'disabled')&&(!q||[c.id,c.name,c.input,c.expected,...c.tags].join(' ').toLowerCase().includes(q))&&(!evAssetState.caseTag||c.tags.includes(evAssetState.caseTag))&&(evAssetState.caseStatus==='active'||(evAssetState.caseStatus==='enabled'?c.enabled:!c.enabled)));}
function evCasesView(){return `<div id="ev-case-results"><div class="ev-library-heading"><button type="button" class="ont-button" onclick="evTab('评测集')">‹ 返回评测集</button><h3>评测用例库</h3></div>${evCaseTable(evVisibleCases())}</div>`;}
function evCaseTable(rows,contentOnly=false){const d=evData(),tags=[...new Set(d.cases.filter(c=>!c.archived).flatMap(c=>c.tags))],headers=['编号','名称','输入','预期结果',evFilterHeader('标签','case','tags',tags.map(t=>({id:t,name:t}))),'版本',evFilterHeader('状态','case','enabled',[{id:'enabled',name:'已启用'},{id:'disabled',name:'已停用'}]),'操作'],items=rows.map(c=>evCaseRow(c)),empty=evAssetEmpty(d.cases.some(c=>!c.archived)?'暂无匹配的评测用例':'暂无评测用例',d.cases.some(c=>!c.archived)?'调整搜索内容或筛选条件后重试。':'点击新建，手动创建或通过 Copilot 生成，也可以导入已有用例。'),toolbar=`<label class="ont-search"><input aria-label="搜索评测用例" placeholder="搜索编号、名称或内容" value="${esc(evAssetState.caseSearch)}" oninput="evAssetState.caseSearch=this.value;evAssetRefresh('case')"><svg viewBox="0 0 18 18"><circle cx="7" cy="7" r="5"/><path d="m11 11 4 4"/></svg></label><div class="ont-head-actions">${evAssetButton('导入',"evImportCases()",'ont-button')}${evCreateMenu('case')}</div>`;return contentOnly?evTableContent(headers,items,empty):evTable(headers,items,empty,toolbar);}
function evCaseRow(c,suiteId='',readonly=false,suite=null){const actions=[{label:'编辑',code:`evEditCase('${c.id}','${suiteId}')`},{label:'发布',code:`evPublishResource('case','${c.id}')`},{label:c.enabled?'停用':'启用',code:`evToggleCase('${c.id}')`}];if(suiteId)actions.push({label:'关联业务任务',code:`evEditCaseBinding('${suiteId}','${c.id}')`});if(suiteId)actions.push({label:'从评测集移除',code:`evRemoveSuiteCase('${suiteId}','${c.id}')`});actions.push({label:'归档',code:`evArchiveCase('${c.id}')`,danger:true});return `<tr><td><span class="ont-id">${esc(c.id)}</span></td><td><button type="button" class="ont-link ev-name-link" onclick="evCaseDetail('${c.id}','${suiteId}')">${esc(c.name)}</button></td><td>${evAssetText(c.input)}</td><td>${evAssetText(c.expected)}</td>${suiteId?`<td>${evCaseBindingColumn(suite||evData().suites.find(s=>s.id===suiteId),c.id,'task')}</td><td>${evCaseBindingColumn(suite||evData().suites.find(s=>s.id===suiteId),c.id,'dimension')}</td>`:''}<td>${evCaseTags(c)}</td><td>${evVersionBadge(c)}</td><td><span class="ont-enabled ${c.enabled?'':'draft'}">${c.enabled?'已启用':'已停用'}</span></td><td><div class="ev-actions">${evAssetButton('查看',`evCaseDetail('${c.id}','${suiteId}')`)}${readonly?'':evMore(actions)}</div></td></tr>`;}

// The input editor keeps uploaded file contents with the case, including published snapshots.
const evCaseAttachmentLimits={count:10,file:10*1024*1024,total:30*1024*1024};
let evCaseInputEditor=null,evCaseInputPalette=null,evCaseAttachmentSequence=0;
function evCaseAttachmentId(){return 'case-file-'+Date.now().toString(36)+'-'+(++evCaseAttachmentSequence);}
function evCaseAttachmentSize(size){return size<1024?size+' B':size<1024*1024?(size/1024).toFixed(1)+' KB':(size/1024/1024).toFixed(1)+' MB';}
function evNormalizeCaseAttachments(raw){
  if(raw===undefined||raw===null)return [];
  const files=typeof raw==='string'?JSON.parse(raw):raw;
  if(!Array.isArray(files)||files.length>evCaseAttachmentLimits.count)throw Error('最多上传 10 个附件');
  const ids=new Set();let total=0;
  return files.map(file=>{
    if(!file||typeof file.name!=='string'||!file.name.trim()||file.name.length>255||typeof file.dataUrl!=='string'||!/^data:[^,]*;base64,[A-Za-z0-9+/]*={0,2}$/.test(file.dataUrl))throw Error('附件内容无效，请重新上传');
    const encoded=file.dataUrl.slice(file.dataUrl.indexOf(',')+1),bytes=Math.floor(encoded.length*3/4)-(encoded.endsWith('==')?2:encoded.endsWith('=')?1:0),size=Number(file.size);
    if(!Number.isSafeInteger(size)||size<0||size!==bytes||size>evCaseAttachmentLimits.file)throw Error('单个附件不能超过 10 MB，附件内容必须完整');
    total+=size;if(total>evCaseAttachmentLimits.total)throw Error('附件总大小不能超过 30 MB');
    let id=typeof file.id==='string'&&/^[\w-]{1,100}$/.test(file.id)?file.id:evCaseAttachmentId();if(ids.has(id))id=evCaseAttachmentId();ids.add(id);
    return {id,name:file.name,size,type:typeof file.type==='string'?file.type:'application/octet-stream',lastModified:Number(file.lastModified)||0,dataUrl:file.dataUrl};
  });
}
function evCaseNativeFields(){return typeof AIOpsEvaluation!=='undefined';}
function evCaseAttachmentRows(files,readonly=false,kind='input'){return (files||[]).map(file=>`<div class="ev-case-attachment"><span class="ev-case-file-icon" aria-hidden="true">▤</span><span class="ev-case-file-info"><b title="${esc(file.name)}">${esc(file.name)}</b><small>${evCaseAttachmentSize(file.size)}</small></span><a class="ont-link" href="${esc(file.dataUrl)}" download="${esc(file.name)}" aria-label="下载附件 ${esc(file.name)}">下载</a>${readonly?'':`<button type="button" class="ev-case-file-remove" aria-label="移除附件 ${esc(file.name)}" onclick="evRemoveCaseAttachment('${file.id}','${kind}')">×</button>`}</div>`).join('');}
function evCaseInputReadOnly(record){return `<div class="ev-case-input-readonly"><textarea aria-label="用例输入" readonly>${esc(record.input||'')}</textarea>${record.inputAttachments?.length?`<div class="ev-case-attachments" aria-label="输入附件">${evCaseAttachmentRows(record.inputAttachments,true)}</div>`:''}</div>`;}
function evCaseInputControl(record){const files=record.inputAttachments||[];return `<div class="ont-field ev-field ev-case-input-field"><label for="ev-case-input">输入<i class="ont-required">*</i></label><div class="ev-case-input-box" ondragover="event.preventDefault()" ondrop="event.preventDefault();evReadCaseAttachments(event.dataTransfer.files)"><textarea id="ev-case-input" name="input" aria-label="用例输入" maxlength="12000" ${files.length?'':'required'} placeholder="发送给 Agent 的评测输入，输入 / 选择 Skill，或上传附件">${esc(record.input||'')}</textarea><div class="ev-case-attachments" id="ev-case-attachments" aria-label="输入附件" ${files.length?'':'hidden'}>${evCaseAttachmentRows(files)}</div><div class="ev-case-input-tools">${evCaseNativeFields()?'':`<button type="button" class="ont-button ev-case-skill-button" onclick="evOpenCaseSkills()" aria-label="选择 Skill"><span aria-hidden="true">/</span> Skill</button>`}<label class="ont-button ev-case-upload-button"><svg viewBox="0 0 16 16" aria-hidden="true"><path d="m5 8 4-4a2 2 0 0 1 3 3l-5 5a3 3 0 0 1-4-4l5-5"/></svg>上传附件<input type="file" multiple aria-label="上传输入附件" onchange="evReadCaseAttachments(this.files);this.value=''"></label><small id="ev-case-upload-status" role="status" aria-live="polite">可拖拽附件，最多 10 个</small></div></div><small>输入 / 或 /skill 选择技能；单个附件不超过 10 MB，总计不超过 30 MB。</small><input type="hidden" name="inputAttachments" id="ev-case-attachment-values" value="${esc(JSON.stringify(files))}"></div>`;}
function evCaseReferenceControl(record,readonly=false){
  const files=record.referenceAttachments||[];
  if(readonly)return `<div class="ev-case-input-readonly">${files.length?`<div class="ev-case-attachments" aria-label="参考附件">${evCaseAttachmentRows(files,true,'reference')}</div>`:'<span class="muted">未添加</span>'}</div>`;
  return `<div class="ont-field ev-field ev-case-input-field"><label>参考附件（非必填）</label><div class="ev-case-input-box" ondragover="event.preventDefault()" ondrop="event.preventDefault();evReadCaseAttachments(event.dataTransfer.files,'reference')"><div class="ev-case-attachments" id="ev-case-reference-attachments" aria-label="参考附件" ${files.length?'':'hidden'}>${evCaseAttachmentRows(files,false,'reference')}</div><div class="ev-case-input-tools"><label class="ont-button ev-case-upload-button">上传参考附件<input type="file" multiple aria-label="上传参考附件" onchange="evReadCaseAttachments(this.files,'reference');this.value=''"></label><small id="ev-case-reference-upload-status" role="status" aria-live="polite">可拖拽附件，最多 10 个</small></div></div><small>单个附件不超过 10 MB，总计不超过 30 MB。</small><input type="hidden" name="referenceAttachments" id="ev-case-reference-attachment-values" value="${esc(JSON.stringify(files))}"></div>`;
}
function evCaseExpectedExtras(record,readonly=false){
  if(!evCaseNativeFields())return '';
  const requirements=readonly?`<textarea aria-label="预期要求" readonly>${esc(record.expectedRequirements||'—')}</textarea>`:`<textarea name="expectedRequirements" aria-label="预期要求" maxlength="12000" placeholder="补充结果应满足的要求">${esc(record.expectedRequirements||'')}</textarea>`;
  return `<div class="ont-wide">${readonly?evField('参考附件（非必填）',evCaseReferenceControl(record,true),'',false):evCaseReferenceControl(record)}</div><div class="ont-wide">${evField('预期要求（非必填）',requirements,'',false)}</div>`;
}
function evCaseSkillTrigger(input){const caret=input.selectionStart??input.value.length,match=/(^|\s)\/(?:skill(?:\s+([^\s/]{0,40}))?|([^\s/]{0,40}))$/.exec(input.value.slice(0,caret));if(!match)return null;return {from:match.index+match[1].length,to:caret,query:match[2]??match[3]??''};}
function evOpenCaseSkills(){const field=document.getElementById('ev-case-input');if(!field)return;const from=field.selectionStart??field.value.length,to=field.selectionEnd??from;if(!evCaseSkillTrigger(field)){const insertion=(from&&!/\s/.test(field.value[from-1])?' ':'')+'/';if(field.value.length-(to-from)+insertion.length>12000){toast('输入不能超过 12,000 字');return;}field.setRangeText(insertion,from,to,'end');}field.focus();field.dispatchEvent(new Event('input',{bubbles:true}));}
function evDisposeCaseInput(){evCaseInputPalette?.destroy();evCaseInputPalette=null;evCaseInputEditor=null;}
function evBindCaseInput(id,suiteId,record){
  evDisposeCaseInput();
  const field=document.getElementById('ev-case-input');if(!field)return;evCaseInputEditor={id,suiteId,scene:studio.scene,attachments:evVersionClone(record.inputAttachments||[]),referenceAttachments:evVersionClone(record.referenceAttachments||[]),loading:false};
  if(typeof ComposerSlashSkills==='undefined')return;
  evCaseInputPalette=ComposerSlashSkills.create({input:field,dock:document.querySelector('.ev-case-input-box'),menuId:'ev-case-skill-menu',className:'ev-case-skill-menu',trigger:evCaseSkillTrigger,insertMany:(input,skills,range)=>{const command=skills.map(skill=>'/'+skill.id).join(' ')+' ';if(input.value.length-(range.to-range.from)+command.length>12000){toast('输入不能超过 12,000 字');return;}input.setRangeText(command,range.from,range.to,'end');},position:menu=>{const rect=field.getBoundingClientRect(),bounds=document.querySelector('.ev-modal')?.getBoundingClientRect()||{left:0,right:innerWidth,top:0,bottom:innerHeight},left=Math.max(8,bounds.left+12),right=Math.min(innerWidth-8,bounds.right-12),bottom=Math.min(innerHeight-8,bounds.bottom-12),width=Math.max(0,Math.min(rect.width,right-left));menu.style.width=width+'px';menu.style.left=Math.max(left,Math.min(rect.left,right-width))+'px';menu.style.maxHeight=Math.min(320,Math.max(100,bottom-bounds.top-24))+'px';menu.style.top=(rect.bottom+menu.offsetHeight+6<=bottom?rect.bottom+6:Math.max(bounds.top+12,rect.top-menu.offsetHeight-6))+'px';}});
}
function evUpdateCaseAttachments(){
  const e=evCaseInputEditor;if(!e||e.scene!==studio.scene)return;
  for(const kind of ['input','reference']){
    const reference=kind==='reference',files=reference?e.referenceAttachments:e.attachments,prefix=reference?'ev-case-reference':'ev-case';
    const list=document.getElementById(prefix+'-attachments'),values=document.getElementById(prefix+'-attachment-values'),status=document.getElementById(prefix+'-upload-status');
    if(list){list.innerHTML=evCaseAttachmentRows(files,false,kind);list.hidden=!files.length;}
    if(values)values.value=JSON.stringify(files);
    if(status)status.textContent=e.loading?'正在读取附件…':files.length?'已上传 '+files.length+' 个 · '+evCaseAttachmentSize(files.reduce((sum,file)=>sum+file.size,0)):'可拖拽附件，最多 10 个';
  }
  const field=document.getElementById('ev-case-input');if(field)field.required=!e.attachments.length;
  document.querySelectorAll('.ev-modal button[type="submit"],.ev-case-upload-button input').forEach(button=>button.disabled=e.loading);
}
function evReadCaseFile(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({id:evCaseAttachmentId(),name:file.name,size:file.size,type:file.type||'application/octet-stream',lastModified:file.lastModified||0,dataUrl:String(reader.result)});reader.onerror=()=>reject(Error('无法读取附件「'+file.name+'」，请重新选择'));reader.onabort=()=>reject(Error('附件读取已取消'));reader.readAsDataURL(file);});}
async function evReadCaseAttachments(fileList,kind='input'){
  const e=evCaseInputEditor,files=Array.from(fileList||[]);if(!e||e.scene!==studio.scene||!files.length||e.loading)return false;
  const key=kind==='reference'?'referenceAttachments':'attachments',current=e[key];
  try{
    if(current.length+files.length>evCaseAttachmentLimits.count)throw Error('最多上传 10 个附件');
    if(files.some(file=>file.size>evCaseAttachmentLimits.file))throw Error('单个附件不能超过 10 MB');
    if([...current,...files].reduce((sum,file)=>sum+file.size,0)>evCaseAttachmentLimits.total)throw Error('附件总大小不能超过 30 MB');
    e.loading=true;evUpdateCaseAttachments();const uploaded=await Promise.all(files.map(evReadCaseFile));
    if(evCaseInputEditor!==e||studio.scene!==e.scene||!document.getElementById('ev-case-input'))return false;
    e[key]=evNormalizeCaseAttachments([...current,...uploaded]);return true;
  }catch(error){if(evCaseInputEditor===e)toast(error.message||'附件上传失败');return false;}finally{if(evCaseInputEditor===e){e.loading=false;evUpdateCaseAttachments();}}
}
function evRemoveCaseAttachment(id,kind='input'){const e=evCaseInputEditor;if(!e||e.loading)return;const key=kind==='reference'?'referenceAttachments':'attachments';e[key]=e[key].filter(file=>file.id!==id);evUpdateCaseAttachments();}

function evCaseDetail(id,suiteId='',selection='current',context='detail'){
  const record=evData().cases.find(c=>c.id===id&&!c.archived);if(!record)return;
  const c=evVersionResolve(record,selection);if(!c)return;
  const bindingRecord=suiteId?evData().suites.find(s=>s.id===suiteId):null,bindingSuite=bindingRecord?evVersionResolve(bindingRecord,evVersionSelection('suite',suiteId)):null,suiteReadonly=!!bindingSuite&&evVersionSelection('suite',suiteId)!=='current';
  const body=`${bindingSuite?`<section class="ont-form-section"><h3>关联业务任务与评估维度</h3>${evCaseBindingSummary(bindingSuite,id)}</section>`:''}<section class="ont-form-section"><h3>基本信息</h3><dl class="ont-mapping"><div><dt>编号</dt><dd>${esc(c.id)}</dd></div><div><dt>名称</dt><dd>${esc(c.name)}</dd></div><div><dt>版本</dt><dd>${esc(c.version)}</dd></div><div><dt>状态</dt><dd><span class="ont-enabled ${c.enabled?'':'draft'}">${c.enabled?'已启用':'已停用'}</span></dd></div><div><dt>标签</dt><dd>${evCaseTags(c)}</dd></div></dl></section><section class="ont-form-section"><h3>评测内容</h3><div class="ont-grid">${evField('输入',evCaseInputReadOnly(c),'',false)}${evField('预期结果',`<textarea aria-label="预期结果" readonly>${esc(c.expected)}</textarea>`,'',false)}${evCaseExpectedExtras(c,true)}</div></section>`;
  const actions=suiteReadonly?`<button type="button" class="ont-button" onclick="evCloseModal()">关闭</button>`:selection==='current'?`<button type="button" class="ont-button" onclick="evEditCase('${c.id}','${suiteId}')">编辑</button><button type="button" class="ont-button strong" onclick="evPublishResource('case','${c.id}')">发布</button>`:`<button type="button" class="ont-button" onclick="evVersionSelect('case','${id}','current','${context}','${studio.scene}','${suiteId}')">返回当前版本</button>`;
  evModal('评测用例详情',body,actions,'',evVersionSwitcher('case',record,selection,context,suiteId));
}
function evBuildCaseDraft(fields={}){const d=evData(),suite=d.suites.find(s=>s.id===fields.suiteId),topic=studioSceneData[d.scene].name;return {name:fields.name||fields['用例名称']||topic+'业务规则与输出校验',input:fields.input||fields['输入']||`请根据${topic}场景的业务输入和已确认规则，生成业务方案，并列出未满足需求、风险及规则依据。`,expected:(fields.expected||fields['预期结果']||'输出完整业务方案，遵循业务约束；缺少数据或规则冲突时明确说明并请求确认。')+(fields.instructions?'\n补充要求：'+fields.instructions:''),inputAttachments:evVersionClone(fields.inputAttachments||[]),...(evCaseNativeFields()?{referenceAttachments:evVersionClone(fields.referenceAttachments||[]),expectedRequirements:fields.expectedRequirements||''}:{}),tags:Array.isArray(fields.tags)?fields.tags:typeof fields.tags==='string'?fields.tags.split(/[,，、]/).map(t=>t.trim()).filter(Boolean):[suite?'业务验收':'正常流程'],version:'V1',enabled:true};}
function evIssueCaseSuiteChange(select){
 const form=select.form||select.closest?.('form'),holder=form?.querySelector?.('#ev-issue-case-bindings');if(!form||!holder)return false;
 const values=new FormData(form),context=typeof evExperimentIssueContext==='function'?evExperimentIssueContext(String(values.get('sourceExperimentId')||''),'all',String(values.get('sourceIssueId')||'')):null;
 const suite=evData().suites.find(item=>item.id===select.value),agentId=context?.run?.snapshot?.agent?.id||context?.experiment?.agentId;
 if(!context||!suite||suite.agentId!==agentId){holder.innerHTML='';return false;}
 holder.innerHTML=evCaseBindingFields(suite,evCaseBindings(suite,context.issue.caseId));holder.querySelectorAll?.('.ev-binding-cascader').forEach(evBindingSync);return true;
}
function evEditCase(id='',suiteId='',draft=null,options={}){
 const d=evData(),c=d.cases.find(c=>c.id===id&&!c.archived);
 if(id&&!c){toast('评测用例已不存在或不属于当前场景');return;}
 if(suiteId&&!d.suites.some(s=>s.id===suiteId)){toast('目标评测集已不存在');return;}
 const v=c||draft||{},bindingSuite=d.suites.find(s=>s.id===suiteId),copilot=!id&&draft&&draft===evState.copilot?.draft&&evState.copilot.kind==='case';
 const suitePicker=options.requireSuite?`<section class="ont-form-section"><h3>评测集</h3>${evField('目标评测集',`<select name="targetSuiteId" aria-label="评测集" required onchange="evIssueCaseSuiteChange(this)"><option value="">请选择评测集</option>${(options.suiteChoices||[]).map(suite=>`<option value="${esc(suite.id)}">${esc(suite.name)}</option>`).join('')}</select>`,'新用例将添加到所选评测集；仅展示当前 Agent 的评测集。')}${(options.suiteChoices||[]).length?'':'<p class="ev-note">当前 Agent 暂无评测集，请先创建评测集。</p>'}</section>`:'';
 const body=`<input type="hidden" name="scene" value="${d.scene}"><input type="hidden" name="copilot" value="${copilot?'true':'false'}">${options.sourceIssueId?`<input type="hidden" name="sourceIssueId" value="${esc(options.sourceIssueId)}"><input type="hidden" name="sourceExperimentId" value="${esc(options.sourceExperimentId||'')}">`:''}${options.optimizationHint?`<p class="ev-note">优化建议：${esc(options.optimizationHint)}</p>`:''}${suitePicker}<section class="ont-form-section"><h3>基本信息</h3><div class="ont-grid">${evField('用例名称',`<input name="name" aria-label="用例名称" maxlength="120" required value="${esc(v.name||'')}" placeholder="请输入用例名称">`)}${evField('标签',`<input name="tags" aria-label="用例标签" value="${esc((v.tags||[]).join('，'))}" maxlength="300" placeholder="正常流程，边界条件，异常处理">`,'使用逗号分隔多个标签',false)}</div></section><section class="ont-form-section"><h3>评测内容</h3><div class="ont-grid"><div class="ont-wide">${evCaseInputControl(v)}</div><div class="ont-wide">${evField('预期结果',`<textarea name="expected" aria-label="预期结果" maxlength="12000" required placeholder="明确应输出的结果、约束和通过标准">${esc(v.expected||'')}</textarea>`)}</div>${evCaseExpectedExtras(v)}</div></section>${options.requireSuite?'<div id="ev-issue-case-bindings"></div>':bindingSuite?evCaseBindingFields(bindingSuite,evCaseBindings(bindingSuite,id)):''}`;
 evModal(options.title||(c?'编辑评测用例':draft?'确认 Copilot 用例草案':'新建评测用例'),body,`<button type="submit" class="ont-button" value="save">保存</button><button type="submit" class="ont-button strong" value="publish">发布</button>`,`evSaveCase(this,'${id}','${suiteId}',event.submitter?.value==='publish')`,c?evVersionSwitcher('case',c,'current','edit',suiteId):'');evBindCaseInput(id,suiteId,v);
}
function evSaveCase(form,id='',suiteId='',publish=false){
  const d=evData(),f=new FormData(form);
  if((f.get('scene')&&f.get('scene')!==d.scene)||(id&&!d.cases.some(c=>c.id===id&&!c.archived))||(suiteId&&!d.suites.some(s=>s.id===suiteId))){toast('当前场景或目标用例已变更，请重新打开表单');return false;}
  const sourceIssueId=String(f.get('sourceIssueId')||''),sourceExperimentId=String(f.get('sourceExperimentId')||'');
  if(sourceIssueId){
   const origin=typeof evExperimentIssueContext==='function'?evExperimentIssueContext(sourceExperimentId,'all',sourceIssueId):null;
   if(!origin||origin.experiment.scene!==d.scene){toast('来源问题已不存在或不属于当前场景，请重新打开用例表单');return false;}
   if(id&&origin.issue.caseId!==id){toast('关联用例已变更，请重新打开用例表单');return false;}
   if(!id){
    const targetSuiteId=String(f.get('targetSuiteId')||suiteId||''),targetSuite=d.suites.find(item=>item.id===targetSuiteId),agentId=origin.run?.snapshot?.agent?.id||origin.experiment.agentId;
    if(!targetSuiteId){toast('请选择评测集');return false;}
    if(!targetSuite||targetSuite.agentId!==agentId){toast('请选择当前 Agent 下可用的评测集');return false;}
    suiteId=targetSuiteId;
   }
  }
  const values={name:String(f.get('name')||'').trim(),input:String(f.get('input')||'').trim(),expected:String(f.get('expected')||'').trim(),tags:[...new Set(String(f.get('tags')||'').split(/[,，、]/).map(t=>t.trim()).filter(Boolean))]};
  let bindings=null;try{if(suiteId)bindings=evReadCaseBindings(d.suites.find(s=>s.id===suiteId),f);}catch(error){toast(error.message);return false;}
  let c=d.cases.find(c=>c.id===id&&!c.archived);
  if(evCaseInputEditor?.loading){toast('附件正在读取，请稍后保存');return false;}
  try{values.inputAttachments=evNormalizeCaseAttachments(f.get('inputAttachments')??c?.inputAttachments??[]);}catch(error){toast(error.message||'附件内容无效，请重新上传');return false;}
  if(evCaseNativeFields()){
    try{values.referenceAttachments=evNormalizeCaseAttachments(f.get('referenceAttachments')??c?.referenceAttachments??[]);}catch(error){toast(error.message||'参考附件内容无效，请重新上传');return false;}
    values.expectedRequirements=String(f.get('expectedRequirements')??c?.expectedRequirements??'').trim();
    if(values.expectedRequirements.length>12000){toast('预期要求不能超过 12,000 字');return false;}
  }
  if(!values.name||(!values.input&&!values.inputAttachments.length)||!values.expected){toast('请补全名称、输入和预期结果');return false;}
  if(c){if(!c.createdAt)c.createdAt=new Date().toISOString();evVersionPrepare(c);Object.assign(c,values);if(sourceIssueId)c.optimizations=[...(c.optimizations||[]),{sourceIssueId,sourceExperimentId,optimizedAt:evExperimentTime()}];}else {c={id:evId('case'),...values,createdAt:new Date().toISOString(),enabled:true,version:'V1',history:[],archived:false,source:sourceIssueId?'问题优化':f.get('copilot')==='true'?'Copilot 生成':'手动录入',...(sourceIssueId?{sourceIssueId,sourceExperimentId}:{})};d.cases.unshift(c);}
  evVersionSave(c);if(publish)evVersionPublish(c);
  if(suiteId){const s=d.suites.find(s=>s.id===suiteId);if(s){evVersionPrepare(s);if(!s.caseIds.includes(c.id))s.caseIds.push(c.id);s.caseBindings={...(s.caseBindings||{}),[c.id]:bindings};evVersionSave(s);}}
  if(!id&&f.get('copilot')==='true'&&typeof evCopilotSaved==='function')evCopilotSaved('case',c);
  evCloseModal();evRender();toast(publish?'评测用例已发布 '+c.version:'评测用例已保存，发布后生成版本');return true;
}
function evToggleCase(id){const c=evData().cases.find(c=>c.id===id&&!c.archived);if(!c)return;c.enabled=!c.enabled;evRender();toast(c.enabled?'用例已启用':'用例已停用');}
function evArchiveCase(id){const c=evData().cases.find(c=>c.id===id&&!c.archived);if(!c)return;const count=evData().suites.filter(s=>s.caseIds.includes(id)).length;evModal('归档评测用例',`<p>确定归档「${esc(c.name)}」？</p><p class="muted">${count?'此用例已关联 '+count+' 个评测集。归档后将从这些评测集的可用用例中移除。':'归档后将不再出现在可用评测用例库中。'}</p>`,`<button type="button" class="ont-button danger" onclick="evConfirmArchiveCase('${id}','${studio.scene}')">归档用例</button>`);}
function evConfirmArchiveCase(id,scene=studio.scene){const d=evData();if(scene!==d.scene){toast('当前场景已变更，请重新操作');return false;}const c=d.cases.find(c=>c.id===id);if(c){c.archived=true;c.enabled=false;}evCloseModal();evRender();toast('评测用例已归档');}
function evRemoveSuiteCase(suiteId,id){const s=evData().suites.find(s=>s.id===suiteId);if(!s)return;evVersionPrepare(s);s.caseIds=s.caseIds.filter(x=>x!==id);if(s.caseBindings)delete s.caseBindings[id];evVersionSave(s);evRender();toast('已从评测集移除，用例库中保留原用例');}
function evOpenCasePicker(suiteId){const d=evData(),s=d.suites.find(s=>s.id===suiteId);if(!s)return;evAssetState.picker={scene:d.scene,suiteId,search:'',tag:'',status:'all',selected:new Set()};const tags=[...new Set(d.cases.filter(c=>!c.archived).flatMap(c=>c.tags))];evModal('从评测用例库选择',`<section class="ont-form-section"><h3>选择用例</h3><p class="muted">添加到「${esc(s.name)}」。已添加的用例不会重复加入。</p><div class="ont-toolbar"><label class="ont-search"><input aria-label="搜索可选评测用例" placeholder="搜索编号、名称或输入" oninput="evAssetState.picker.search=this.value;evRefreshCasePicker()"><svg viewBox="0 0 18 18"><circle cx="7" cy="7" r="5"/><path d="m11 11 4 4"/></svg></label><div class="ont-head-actions"><select class="ont-button" aria-label="筛选可选用例标签" onchange="evAssetState.picker.tag=this.value;evRefreshCasePicker()"><option value="">全部标签</option>${tags.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('')}</select><select class="ont-button" aria-label="筛选可选用例状态" onchange="evAssetState.picker.status=this.value;evRefreshCasePicker()"><option value="all">全部状态</option><option value="enabled">已启用</option><option value="disabled">已停用</option></select></div></div><div id="ev-picker-results"></div></section>${evCaseBindingFields(s,[],true)}`,`<span id="ev-picker-count" class="muted">已选择 0 项</span><button type="button" id="ev-picker-add" class="ont-button strong" disabled onclick="evApplyCasePicker()">添加到评测集</button>`);document.querySelector('.ev-modal')?.classList.add('ev-wide-modal');evRefreshCasePicker();}
function evRefreshCasePicker(){const p=evAssetState.picker;if(!p||p.scene!==studio.scene)return;const d=evData(),s=d.suites.find(s=>s.id===p.suiteId);if(!s)return;const q=p.search.toLowerCase(),rows=d.cases.filter(c=>!c.archived&&(!q||[c.id,c.name,c.input].join(' ').toLowerCase().includes(q))&&(!p.tag||c.tags.includes(p.tag))&&(p.status==='all'||c.enabled===(p.status==='enabled'))),target=document.getElementById('ev-picker-results');if(target)target.innerHTML=evTable(['编号','名称','输入','标签','状态','选择'],rows.map(c=>`<tr><td><span class="ont-id">${esc(c.id)}</span></td><td>${esc(c.name)}${s.caseIds.includes(c.id)?'<small class="muted"> · 已添加</small>':''}</td><td>${evAssetText(c.input)}</td><td>${evCaseTags(c)}</td><td><span class="ont-enabled ${c.enabled?'':'draft'}">${c.enabled?'已启用':'已停用'}</span></td><td><input type="checkbox" aria-label="选择用例 ${esc(c.name)}" ${s.caseIds.includes(c.id)?'disabled checked':p.selected.has(c.id)?'checked':''} onchange="evPickCase('${c.id}',this.checked)"></td></tr>`),evAssetEmpty('暂无匹配的评测用例','调整搜索或筛选条件后重试。'));evUpdatePickerCount();}
function evPickCase(id,checked){const p=evAssetState.picker;if(!p)return;if(checked)p.selected.add(id);else p.selected.delete(id);evUpdatePickerCount();}
function evUpdatePickerCount(){const p=evAssetState.picker;if(!p)return;const n=document.getElementById('ev-picker-count'),b=document.getElementById('ev-picker-add');if(n)n.textContent='已选择 '+p.selected.size+' 项';if(b)b.disabled=!p.selected.size;}
function evApplyCasePicker(){const p=evAssetState.picker,d=evData();if(!p||p.scene!==d.scene)return;const s=d.suites.find(s=>s.id===p.suiteId);if(!s)return;let bindings;try{bindings=evReadCaseBindings(s,new FormData(document.getElementById('ev-form')));}catch(error){toast(error.message);return false;}const valid=[...p.selected].filter(id=>d.cases.some(c=>c.id===id&&!c.archived)&&!s.caseIds.includes(id));if(valid.length){evVersionPrepare(s);s.caseIds.push(...valid);s.caseBindings=s.caseBindings||{};valid.forEach(id=>s.caseBindings[id]=evVersionClone(bindings));evVersionSave(s);}evAssetState.picker=null;evCloseModal();evRender();toast('已添加 '+valid.length+' 条评测用例');}
function evImportCases(suiteId=''){evAssetState.import={scene:studio.scene,suiteId,rows:[],errors:[],filename:'',loading:false};evModal('导入评测用例',`<p class="muted">支持 CSV / JSON 文件。必填字段：名称、输入、预期结果；可选字段：标签、版本、状态。</p><div class="ev-upload-zone ev-import-zone" ondragover="event.preventDefault()" ondrop="event.preventDefault();evReadImport(event.dataTransfer.files[0])"><span class="ev-empty-icon">⇧</span><b>选择文件，或拖拽文件到这里</b><label class="ont-button ev-file-button">选择 CSV / JSON<input type="file" accept=".csv,.json,text/csv,application/json" aria-label="选择评测用例文件" onchange="evReadImport(this.files[0])"></label><small>CSV 支持带引号的逗号与换行；标签使用分号分隔。单次最多 1,000 条，文件不超过 5 MB。</small></div><div class="ev-import-template">${evAssetButton('下载 CSV 模板',"evDownloadCaseTemplate()")}</div><div id="ev-import-preview" class="ev-import-preview" aria-live="polite"></div>${suiteId?evCaseBindingFields(evData().suites.find(s=>s.id===suiteId),[],true):''}`,`<button type="button" id="ev-import-apply" class="ont-button strong" disabled onclick="evImportApply()">导入用例</button>`);document.querySelector('.ev-modal')?.classList.add('ev-wide-modal');}
function evParseCsv(text){const rows=[];let row=[],field='',quoted=false;const src=text.replace(/^\uFEFF/,'');for(let i=0;i<src.length;i++){const ch=src[i];if(quoted){if(ch==='"'&&src[i+1]==='"'){field+='"';i++;}else if(ch==='"')quoted=false;else field+=ch;}else if(ch==='"'){if(field.trim())throw Error('CSV 引号必须位于字段开头');quoted=true;}else if(ch===','){row.push(field);field='';}else if(ch==='\n'||ch==='\r'){if(ch==='\r'&&src[i+1]==='\n')i++;row.push(field);if(row.some(x=>x.trim()))rows.push(row);row=[];field='';}else field+=ch;}if(quoted)throw Error('CSV 存在未闭合的引号');row.push(field);if(row.some(x=>x.trim()))rows.push(row);if(!rows.length)throw Error('文件为空');const headers=rows.shift().map(v=>v.trim());if(new Set(headers).size!==headers.length)throw Error('CSV 表头存在重复字段');return rows.map((r,index)=>{if(r.length!==headers.length)throw Error('第 '+(index+2)+' 行列数与表头不一致');return Object.fromEntries(headers.map((h,i)=>[h,r[i]]));});}
function evValidateImportRows(records){if(!Array.isArray(records))throw Error('JSON 顶层应为用例数组，或包含 cases 数组的对象');if(!records.length)throw Error('文件中没有用例');if(records.length>1000)throw Error('单次最多导入 1,000 条用例');const errors=[],rows=[];records.forEach((r,i)=>{if(!r||typeof r!=='object'||Array.isArray(r)){errors.push('第 '+(i+1)+' 条不是有效的用例对象');return;}const read=(key,cn,alt='')=>r[key]??r[cn]??(alt?r[alt]:undefined),name=read('name','名称','用例名称'),input=read('input','输入'),expected=read('expected','预期结果','expectedResult'),rawTags=read('tags','标签')??'',version=read('version','版本')||'V1',rawEnabled=read('enabled','状态');if([name,input,expected].some(v=>typeof v!=='string'||!v.trim())){errors.push('第 '+(i+1)+' 条缺少名称、输入或预期结果');return;}if(!/^V[1-9]\d*$/.test(String(version))){errors.push('第 '+(i+1)+' 条版本格式应为 V1、V2…');return;}if(rawEnabled!==undefined&&!['true','false','启用','停用','已启用','已停用',''].includes(String(rawEnabled).trim())){errors.push('第 '+(i+1)+' 条状态应为 启用/停用 或 true/false');return;}if(name.length>120||input.length>12000||expected.length>12000){errors.push('第 '+(i+1)+' 条内容过长（名称上限 120 字，输入和预期结果各 12,000 字）');return;}const tags=(Array.isArray(rawTags)?rawTags.map(String):String(rawTags).split(/[,;；，、]/)).map(v=>v.trim()).filter(Boolean);rows.push({name:name.trim(),input:input.trim(),expected:expected.trim(),tags:[...new Set(tags)],version:String(version),enabled:!['false','停用','已停用'].includes(String(rawEnabled).trim()),archived:false,source:'上传导入'});});return {rows,errors};}
async function evReadImport(file){const pending=evAssetState.import;if(!pending||!file)return;pending.rows=[];pending.errors=[];pending.filename=file.name;pending.loading=true;evRenderImportPreview();try{if(!/\.(csv|json)$/i.test(file.name))throw Error('请选择 .csv 或 .json 文件');if(file.size>5*1024*1024)throw Error('文件不能超过 5 MB');const src=await file.text();if(evAssetState.import!==pending||pending.scene!==studio.scene)return;let records;if(/\.json$/i.test(file.name)){const parsed=JSON.parse(src.replace(/^\uFEFF/,''));records=Array.isArray(parsed)?parsed:parsed&&parsed.cases;}else records=evParseCsv(src);const parsed=evValidateImportRows(records);pending.rows=parsed.rows;pending.errors=parsed.errors;}catch(error){pending.errors=[error.message||'文件读取失败'];}finally{if(evAssetState.import===pending){pending.loading=false;evRenderImportPreview();}}}
function evRenderImportPreview(){const state=evAssetState.import,target=document.getElementById('ev-import-preview'),button=document.getElementById('ev-import-apply');if(!state||!target)return;if(button){button.disabled=state.loading||!state.rows.length||!!state.errors.length;button.textContent=state.rows.length?'导入 '+state.rows.length+' 条用例':'导入用例';}target.innerHTML=state.loading?'<p class="muted">正在读取文件…</p>':state.errors.length?`<div class="ont-error"><b>文件校验未通过</b><ul>${state.errors.slice(0,8).map(e=>`<li>${esc(e)}</li>`).join('')}</ul>${state.errors.length>8?`<small>另有 ${state.errors.length-8} 项错误</small>`:''}<p>请修正文件后重新选择，当前未导入任何用例。</p></div>`:state.rows.length?`<div class="ev-import-summary"><b>${esc(state.filename)}</b><span>校验通过 · ${state.rows.length} 条用例</span></div>${evTable(['名称','输入','预期结果','标签'],state.rows.slice(0,5).map(c=>`<tr><td>${esc(c.name)}</td><td>${evAssetText(c.input)}</td><td>${evAssetText(c.expected)}</td><td>${evCaseTags(c)}</td></tr>`))}${state.rows.length>5?'<small>预览前 5 条；确认后导入全部用例。</small>':''}`:'';}
function evImportApply(){const state=evAssetState.import,d=evData();if(!state||state.scene!==d.scene||state.loading||state.errors.length||!state.rows.length)return;const suite=state.suiteId?d.suites.find(s=>s.id===state.suiteId):null;if(state.suiteId&&!suite){toast('目标评测集已不存在');return;}let bindings;try{if(suite)bindings=evReadCaseBindings(suite,new FormData(document.getElementById('ev-form')));}catch(error){toast(error.message);return false;}const createdAt=new Date().toISOString(),rows=state.rows.map(r=>({id:evId('case'),...r,tags:[...r.tags],createdAt}));rows.forEach(evVersionSave);d.cases.unshift(...rows);if(suite){evVersionPrepare(suite);suite.caseIds.push(...rows.map(r=>r.id));suite.caseBindings=suite.caseBindings||{};rows.forEach(c=>suite.caseBindings[c.id]=evVersionClone(bindings));evVersionSave(suite);}evAssetState.import=null;evCloseModal();evRender();toast('已导入 '+rows.length+' 条评测用例');}
function evDownloadCaseTemplate(){const text='\uFEFF名称,输入,预期结果,标签,版本,状态\r\n"业务规则校验","请根据已确认规则生成业务方案。","输出完整方案并列出规则依据；规则冲突时请求确认。","正常流程;业务验收",V1,启用\r\n',url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='评测用例导入模板.csv';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}

// Coverage belongs to the suite membership, so reusing a case never changes another suite.
function evCaseBindings(s,caseId){
 if(!s)return [];
 const tasks=evSuiteLinkedTasks(s);
 return (s.caseBindings?.[caseId]||[]).flatMap(binding=>{const task=tasks.find(t=>t.id===binding.taskId);if(!task)return [];const names=new Set((task.dimensions||[]).map(d=>d.name));return [{taskId:task.id,dimensionNames:[...new Set(binding.dimensionNames||[])].filter(name=>names.has(name))}];});
}
function evSuiteCoveredTasks(s){const ids=new Set(evSuiteCases(s).flatMap(c=>evCaseBindings(s,c.id).map(b=>b.taskId)));return evSuiteLinkedTasks(s).filter(t=>ids.has(t.id));}
function evSuiteCoverageMetrics(s){
 const cases=evSuiteCases(s),tasks=evSuiteLinkedTasks(s),coveredTasks=evSuiteCoveredTasks(s),dimensions=new Set(tasks.flatMap(t=>(t.dimensions||[]).map(d=>JSON.stringify([t.id,d.name])))),covered=new Set(cases.flatMap(c=>evCaseBindings(s,c.id).flatMap(b=>b.dimensionNames.map(name=>JSON.stringify([b.taskId,name])))));
 return [{id:'suite-case-count',label:'用例数量',value:cases.length,unit:'条',hint:'本评测集未归档的用例数量；包含启用与停用用例。'},
 {id:'suite-task-coverage',label:'业务任务覆盖率',value:tasks.length?coveredTasks.length/tasks.length*100:null,format:'rate',hint:`已覆盖 ${coveredTasks.length} / 配置 ${tasks.length} 个业务任务。至少一条未归档用例关联该任务即覆盖；仅配置任务不算覆盖。`},
 {id:'suite-dimension-coverage',label:'评估维度覆盖率',value:dimensions.size?covered.size/dimensions.size*100:null,format:'rate',hint:`已覆盖 ${covered.size} / 配置 ${dimensions.size} 个评估维度，按任务与维度名称组合去重；无维度时显示 —。`}];
}
function evCaseBindingSummary(s,id){const bindings=evCaseBindings(s,id),tasks=evSuiteLinkedTasks(s);return bindings.length?`<div class="ev-binding-summary">${bindings.map(b=>`<div><b>${esc(tasks.find(t=>t.id===b.taskId)?.name||b.taskId)}</b><small>${esc(b.dimensionNames.join('、')||'该任务暂无评估维度')}</small></div>`).join('')}</div>`:'<span class="muted">未关联</span>';}
function evCaseBindingColumn(s,id,kind){const bindings=evCaseBindings(s,id),tasks=evSuiteLinkedTasks(s);return bindings.length?`<div class="ev-binding-summary">${bindings.map(b=>{const task=tasks.find(t=>t.id===b.taskId);return `<div>${kind==='task'?esc(task?.name||b.taskId):`<small title="${esc(task?.name||b.taskId)}">${esc(b.dimensionNames.join('、')||'暂无评估维度')}</small>`}</div>`;}).join('')}</div>`:'<span class="muted">未关联</span>';}
function evCaseBindingFields(s,bindings=[],batch=false){
 const tasks=evSuiteLinkedTasks(s),active=Math.max(0,tasks.findIndex(t=>bindings.some(b=>b.taskId===t.id))),dimensionCount=bindings.reduce((n,b)=>n+b.dimensionNames.length,0);
 return `<section class="ont-form-section ev-case-binding"><h3>关联业务任务与评估维度 <i class="ont-required">*</i></h3><p class="ev-note">${batch?'以下关联应用于本次选中的所有用例，添加后可逐条调整。':'左侧选择业务任务，右侧多选对应评估维度。'}关联仅在当前评测集中生效。</p><input type="hidden" name="coverageBinding" value="true"><details class="ev-multiselect ev-binding-cascader" onkeydown="evBindingKey(event,this)"><summary class="ev-multiselect-trigger" aria-label="选择业务任务与评估维度"><span data-ev-binding-label>${bindings.length?'已选 '+bindings.length+' 个业务任务 · '+dimensionCount+' 个评估维度':'请选择业务任务与评估维度'}</span>${evDropdownArrow()}</summary><div class="ev-choice-popover ev-binding-popover" data-ev-popover role="group" aria-label="业务任务与评估维度选项"><header><b>业务任务 / 评估维度</b><button type="button" class="ont-link" onclick="evBindingClear(this)">清空</button></header><div class="ev-binding-columns"><div class="ev-binding-task-list" role="group" aria-label="业务任务选项">${tasks.map((t,i)=>{const binding=bindings.find(b=>b.taskId===t.id);return `<div class="ev-binding-task-option ${i===active?'active':''}" data-binding-task-row="${i}"><input type="checkbox" name="coverageTaskIds" value="${esc(t.id)}" data-binding-task="${i}" aria-label="选择业务任务：${esc(t.name)}" ${binding?'checked':''} onchange="evBindingTaskChange(this)"><button type="button" aria-pressed="${i===active}" onclick="evBindingActivate(this,${i})"><span>${esc(t.name)}</span><small data-binding-count>${binding?.dimensionNames.length||0} / ${(t.dimensions||[]).length}</small><span aria-hidden="true">›</span></button></div>`;}).join('')||'<p class="muted">请先配置业务任务</p>'}</div><div class="ev-binding-dimension-list">${tasks.map((t,i)=>{const binding=bindings.find(b=>b.taskId===t.id);return `<div data-binding-panel="${i}" role="group" aria-label="${esc(t.name)}的评估维度" ${i===active?'':'hidden'}><h4>${esc(t.name)}</h4>${(t.dimensions||[]).map(d=>`<label title="${esc(d.description||'')}"><input type="checkbox" name="coverageDimensions" data-binding-dimension="${i}" value="${esc(JSON.stringify([t.id,d.name]))}" ${binding?.dimensionNames.includes(d.name)?'checked':''} onchange="evBindingDimensionChange(this)"><span>${esc(d.name||'未命名维度')}</span></label>`).join('')||'<p class="muted">该任务暂无评估维度，可勾选左侧任务直接关联。</p>'}</div>`;}).join('')}</div></div><footer><span data-binding-total>已选 ${bindings.length} 个任务 · ${dimensionCount} 个维度</span><button type="button" class="ont-button strong" onclick="evClosePopover(this.closest('details'),true)">完成</button></footer></div></details></section>`;
}
function evBindingActivate(node,index){const root=node.closest('.ev-binding-cascader');root.querySelectorAll('[data-binding-task-row]').forEach(row=>{const active=row.dataset.bindingTaskRow===String(index);row.classList.toggle('active',active);row.querySelector('button').setAttribute('aria-pressed',String(active));});root.querySelectorAll('[data-binding-panel]').forEach(panel=>panel.hidden=panel.dataset.bindingPanel!==String(index));evPositionPopover(root);}
function evBindingSync(root){let tasks=0,dimensions=0;root.querySelectorAll('[data-binding-task]').forEach(input=>{const items=[...root.querySelectorAll('[data-binding-dimension="'+input.dataset.bindingTask+'"]')],selected=items.filter(item=>item.checked).length;if(items.length)input.checked=selected>0;input.indeterminate=selected>0&&selected<items.length;input.setAttribute('aria-checked',input.indeterminate?'mixed':String(input.checked));if(input.checked)tasks++;dimensions+=selected;const count=input.closest('[data-binding-task-row]').querySelector('[data-binding-count]');if(count)count.textContent=selected+' / '+items.length;});const label=root.querySelector('[data-ev-binding-label]'),total=root.querySelector('[data-binding-total]');if(label)label.textContent=tasks?'已选 '+tasks+' 个业务任务 · '+dimensions+' 个评估维度':'请选择业务任务与评估维度';if(total)total.textContent='已选 '+tasks+' 个任务 · '+dimensions+' 个维度';}
function evBindingTaskChange(input){const root=input.closest('.ev-binding-cascader'),index=input.dataset.bindingTask;root.querySelectorAll('[data-binding-dimension="'+index+'"]').forEach(item=>item.checked=input.checked);evBindingActivate(input,Number(index));evBindingSync(root);}
function evBindingDimensionChange(input){evBindingSync(input.closest('.ev-binding-cascader'));}
function evBindingClear(node){const root=node.closest('.ev-binding-cascader');root.querySelectorAll('input[type="checkbox"]').forEach(input=>input.checked=false);evBindingSync(root);}
function evBindingKey(event,root){if(!root.open)return;const target=event.target,row=target.closest('[data-binding-task-row]');if(row&&['ArrowDown','ArrowUp','ArrowRight'].includes(event.key)){event.preventDefault();const rows=[...root.querySelectorAll('[data-binding-task-row]')],index=rows.indexOf(row);if(event.key==='ArrowRight')root.querySelector('[data-binding-panel="'+index+'"] input')?.focus();else{const next=(index+(event.key==='ArrowDown'?1:-1)+rows.length)%rows.length;evBindingActivate(target,next);rows[next].querySelector('button').focus();}}else if(target.matches('[data-binding-dimension]')&&event.key==='ArrowLeft'){event.preventDefault();root.querySelector('[data-binding-task-row="'+target.dataset.bindingDimension+'"] button')?.focus();}}
function evReadCaseBindings(s,form){
 const tasks=evSuiteLinkedTasks(s),ids=[...new Set(form.getAll('coverageTaskIds'))];
 if(!ids.length)throw Error('请至少关联一个业务任务，并选择其评估维度');
 const dimensions=form.getAll('coverageDimensions').map(value=>{try{const pair=JSON.parse(value);if(!Array.isArray(pair)||pair.length!==2)throw Error();return pair;}catch(error){throw Error('评估维度关联无效，请重新选择');}});
 if(ids.some(id=>!tasks.some(t=>t.id===id))||dimensions.some(([id,name])=>!ids.includes(id)||!tasks.find(t=>t.id===id)?.dimensions?.some(d=>d.name===name)))throw Error('关联必须属于该评测集选定的业务任务及评估维度');
 return ids.map(id=>{const task=tasks.find(t=>t.id===id),dimensionNames=[...new Set(dimensions.filter(pair=>pair[0]===id).map(pair=>pair[1]))];if(task.dimensions?.length&&!dimensionNames.length)throw Error('请为「'+task.name+'」至少选择一个评估维度');return {taskId:id,dimensionNames};});
}
function evEditCaseBinding(suiteId,caseId){const s=evData().suites.find(s=>s.id===suiteId);if(!s||!s.caseIds.includes(caseId)||evVersionSelection('suite',suiteId)!=='current')return;evModal('关联业务任务与评估维度',`<input type="hidden" name="scene" value="${studio.scene}">${evCaseBindingFields(s,evCaseBindings(s,caseId))}`,`<button type="submit" class="ont-button strong">保存关联</button>`,`evSaveCaseBinding(this,'${suiteId}','${caseId}')`);}
function evSaveCaseBinding(form,suiteId,caseId){const f=new FormData(form),s=evData().suites.find(s=>s.id===suiteId);if(f.get('scene')!==studio.scene||!s||!s.caseIds.includes(caseId)||evVersionSelection('suite',suiteId)!=='current'){toast('评测集或场景已变更，请重新操作');return false;}let bindings;try{bindings=evReadCaseBindings(s,f);}catch(error){toast(error.message);return false;}evVersionPrepare(s);s.caseBindings={...(s.caseBindings||{}),[caseId]:bindings};evVersionSave(s);evCloseModal();evRender();toast('关联已保存，覆盖指标已更新');return true;}
